mapper.select:
SELECT DISTINCT M12.MACHINE AS VALUE_COL, M12.SAP_WRK_NM AS TEXT_COL FROM TB_MAS012 M12, TB_MAS013 M13 WHERE M12.PROC_CD = M13.PROC_CD(+)
AND M13.WERKS = #{WERKS}
AND M12.PROC_CD = #{PROC_CD}
AND TRIM(M12.MACHINE) IS NOT NULL ORDER BY M12.MACHINE

{
	CALL SP_SCH01_S01(
		#{P_TYPE, mode=IN, jdbcType=VARCHAR, javaType=String},
		#{P_JSON_STR, mode=IN, jdbcType=VARCHAR, javaType=String},
		#{P_SUCCESS, mode=OUT, jdbcType=VARCHAR, javaType=String},
		#{P_RS_LIST, mode=OUT, jdbcType=CURSOR, javaType=ResultSet, resultMap=resultMap}
	)
}

